solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

struct ProcEvent { bool start; std::uint32_t pid; std::uint32_t parent; std::uint64_t time; };

class ProcessTable
{
public:
    void apply(const ProcEvent& e)
    {
        Record* running{ findRunning(e.pid) };
        if (e.start)
        {
            if (running) { running->exited = true; running->exit = e.time; }
            m_records.push_back({ e.pid, e.parent, e.time, 0, false });
        }
        else if (running) { running->exited = true; running->exit = e.time; }
        else ++m_unknownExits;
    }

    int alive() const { return static_cast<int>(std::count_if(m_records.begin(), m_records.end(), [](const Record& r) { return !r.exited; })); }
    int unknownExits() const { return m_unknownExits; }

    std::vector<std::string> tree() const
    {
        std::vector<const Record*> live;
        for (const Record& r : m_records) if (!r.exited) live.push_back(&r);
        std::sort(live.begin(), live.end(), [](const Record* a, const Record* b) { return a->start != b->start ? a->start < b->start : a->pid < b->pid; });
        auto parentOf = [&](const Record* r) -> const Record* {
            for (const Record* p : live) if (p != r && p->pid == r->parent && p->start <= r->start) return p;
            return nullptr;
        };
        std::vector<std::string> out;
        std::vector<std::pair<const Record*, int>> stack;
        for (auto it{ live.rbegin() }; it != live.rend(); ++it) if (!parentOf(*it)) stack.push_back({ *it, 0 });
        while (!stack.empty())
        {
            const auto [r, depth] { stack.back() };
            stack.pop_back();
            out.push_back(std::string(static_cast<std::size_t>(depth) * 2, ' ') + std::to_string(r->pid));
            for (auto it{ live.rbegin() }; it != live.rend(); ++it) if (parentOf(*it) == r) stack.push_back({ *it, depth + 1 });
        }
        return out;
    }

    std::string lifetime(std::uint32_t pid) const
    {
        for (auto it{ m_records.rbegin() }; it != m_records.rend(); ++it)
        {
            if (it->pid != pid) continue;
            if (!it->exited) return "running";
            return "ran " + std::to_string((it->exit - it->start) / 10'000) + " ms";
        }
        return "unknown";
    }

private:
    struct Record { std::uint32_t pid; std::uint32_t parent; std::uint64_t start; std::uint64_t exit; bool exited; };

    Record* findRunning(std::uint32_t pid)
    {
        for (Record& r : m_records) if (r.pid == pid && !r.exited) return &r;
        return nullptr;
    }

    std::vector<Record> m_records;
    int m_unknownExits{ 0 };
};

unitTests:
using Lines = std::vector<std::string>;
ProcEvent start(std::uint32_t pid, std::uint32_t parent, std::uint64_t t) { return { true, pid, parent, t * 10'000 }; }
ProcEvent stop(std::uint32_t pid, std::uint64_t t) { return { false, pid, 0, t * 10'000 }; }
TEST("a tree") {
    ProcessTable p; p.apply(start(4, 0, 1)); p.apply(start(100, 4, 2)); p.apply(start(200, 100, 3)); p.apply(start(300, 4, 4));
    CHECK_EQ(p.tree(), (Lines{ "4", "  100", "    200", "  300" })); CHECK_EQ(p.alive(), 4);
}
TEST("exits make orphans") {
    ProcessTable p; p.apply(start(4, 0, 1)); p.apply(start(100, 4, 2)); p.apply(start(200, 100, 3)); p.apply(start(300, 4, 4)); p.apply(stop(100, 10));
    CHECK_EQ(p.tree(), (Lines{ "4", "  300", "200" })); CHECK_EQ(p.lifetime(100), std::string("ran 8 ms")); CHECK_EQ(p.lifetime(200), std::string("running"));
}
TEST("reused ids") {
    ProcessTable p; p.apply(start(4, 0, 1)); p.apply(start(100, 4, 2)); p.apply(start(200, 100, 3)); p.apply(stop(100, 10)); p.apply(start(100, 4, 20));
    CHECK_EQ(p.tree(), (Lines{ "4", "  100", "200" })); CHECK_EQ(p.lifetime(100), std::string("running"));
    p.apply(start(200, 4, 30)); CHECK_EQ(p.alive(), 3); CHECK_EQ(p.tree(), (Lines{ "4", "  100", "  200" }));
}
TEST("unknown exits") { ProcessTable p; p.apply(stop(999, 5)); CHECK_EQ(p.unknownExits(), 1); CHECK_EQ(p.lifetime(999), std::string("unknown")); CHECK(p.tree().empty()); }

